import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "cn"

const badgeVariants = cva(
  "group/badge inline-flex h-5 w-fit shrink-0 items-center justify-center gap-1 overflow-hidden rounded-4xl border border-transparent px-2 py-0.5 text-xs font-medium whitespace-nowrap transition-all focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&>svg]:pointer-events-none [&>svg]:size-3!",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground [a]:hover:bg-primary/80",
        secondary:
          "bg-secondary text-secondary-foreground [a]:hover:bg-secondary/80",
        destructive:
          "bg-destructive/10 text-destructive focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:focus-visible:ring-destructive/40 [a]:hover:bg-destructive/20",
        // A status badge needs to say "this went right" as clearly as it says "this went
        // wrong". Without these, every non-failure state falls back to `secondary` and a
        // status column becomes a row of identical grey pills.
        success:
          "bg-success/10 text-success focus-visible:ring-success/20 dark:bg-success/20 dark:focus-visible:ring-success/40 [a]:hover:bg-success/20",
        warning:
          "bg-warning/10 text-warning focus-visible:ring-warning/20 dark:bg-warning/20 dark:focus-visible:ring-warning/40 [a]:hover:bg-warning/20",
        outline:
          "border-border text-foreground [a]:hover:bg-muted [a]:hover:text-muted-foreground",
        ghost:
          "hover:bg-muted hover:text-muted-foreground dark:hover:bg-muted/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
)

/*
 * React Aria has no Slot and no asChild: composition happens by rendering RAC's own
 * components, not by handing props to someone else's element. `render` is this system's
 * API on all three trees though, so it is honoured here by cloning the given element with
 * the badge's classes -- a badge is presentational, so there is no behaviour to lose.
 */
type BadgeProps = React.ComponentProps<"span"> &
  VariantProps<typeof badgeVariants> & {
    render?: React.ReactElement
  }

function Badge({
  className,
  variant = "default",
  render,
  children,
  ...props
}: BadgeProps) {
  const classes = cn(badgeVariants({ variant }), className)

  if (render) {
    const childProps = render.props as { className?: string }
    return React.cloneElement(render, {
      ...props,
      "data-slot": "badge",
      "data-variant": variant,
      className: cn(classes, childProps.className),
    } as Record<string, unknown>)
  }

  return (
    <span data-slot="badge" data-variant={variant} className={classes} {...props}>
      {children}
    </span>
  )
}

export { Badge, badgeVariants }
